alter table public.timeline_daw_private_midi_clips add column if not exists artifact_id text,add column if not exists artifact_uri text,add column if not exists artifact_checksum text,add column if not exists artifact_byte_length bigint,add column if not exists artifact_sample_rate integer,add column if not exists artifact_frame_count bigint,add column if not exists rendered_revision bigint;
alter table public.timeline_daw_private_midi_clips drop constraint if exists timeline_daw_private_midi_artifact_complete;
alter table public.timeline_daw_private_midi_clips add constraint timeline_daw_private_midi_artifact_complete check((artifact_uri is null and artifact_checksum is null) or (artifact_id is not null and artifact_uri is not null and artifact_checksum~'^sha256:[a-f0-9]{64}$' and artifact_byte_length>0 and artifact_sample_rate between 8000 and 384000 and artifact_frame_count>0 and rendered_revision>=0));
